-- Approved D batch, private database authority; saved versions stay frozen.
create or replace function ml_private.p3d_spawn_pool(s jsonb,pool jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare catalog jsonb; result jsonb;begin
 if s->>'catalogVersion'<>'web-v0.1.15' then return pool;end if;catalog:=ml_private.version_catalog(s->>'catalogVersion');
 select coalesce(jsonb_agg(v order by ord),'[]') into result from jsonb_array_elements(pool) with ordinality q(v,ord) where
 (select count(*) from ml_private.arr(s->'selected') p where p<>'null'::jsonb and catalog#>>array['sourceCatalog','characters',p#>>'{}','spawnRegion']=catalog#>>array['sourceCatalog','characters',v#>>'{}','spawnRegion']) <
 (select count(*) from ml_private.arr(catalog#>'{mapDefinition,cells}') c where c->>'region'=catalog#>>array['sourceCatalog','characters',v#>>'{}','spawnRegion']);return result;end $$;
create or replace function ml_private.p3d_spawn_safe(s jsonb) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$declare i integer; a integer; pool jsonb; catalog jsonb:=ml_private.version_catalog(s->>'catalogVersion'); r text; slots integer; extra integer; n integer; safe boolean:=true; picked jsonb; next_s jsonb;begin
 if s->>'catalogVersion'<>'web-v0.1.15' or (s->>'cursor')::int=4 then return true;end if;
 for i in (s->>'cursor')::int..3 loop a:=(s->'order'->>i)::int;select coalesce(jsonb_agg(v order by ord),'[]') into pool from jsonb_array_elements(ml_private.p3d_spawn_pool(s,s->'pools'->(s->'teams'->>a))) with ordinality q(v,ord) where not(s->'selected' @> jsonb_build_array(v));
 if jsonb_array_length(pool)<3 then return false;end if;extra:=0;
 for r in select distinct catalog#>>array['sourceCatalog','characters',v#>>'{}','spawnRegion'] from ml_private.arr(pool) v loop
 select count(*) into slots from ml_private.arr(catalog#>'{mapDefinition,cells}') c where c->>'region'=r;
 slots:=slots-(select count(*) from ml_private.arr(s->'selected') p where p<>'null'::jsonb and catalog#>>array['sourceCatalog','characters',p#>>'{}','spawnRegion']=r);
 if slots<=i-(s->>'cursor')::int then select count(*) into n from ml_private.arr(pool) p where catalog#>>array['sourceCatalog','characters',p#>>'{}','spawnRegion']=r;extra:=extra+greatest(0,n-slots);end if;end loop;
 if jsonb_array_length(pool)-(i-(s->>'cursor')::int)-extra<3 then safe:=false;end if;end loop;
 if safe then return true;end if;a:=(s->'order'->>(s->>'cursor')::int)::int;
 for picked in select * from ml_private.arr(ml_private.p3d_spawn_pool(s,s->'pools'->(s->'teams'->>a))) p where not(s->'selected' @> jsonb_build_array(p)) loop
 next_s:=jsonb_set(s,array['selected',a::text],picked);next_s:=jsonb_set(next_s,'{cursor}',to_jsonb((s->>'cursor')::int+1));if not ml_private.p3d_spawn_safe(next_s) then return false;end if;end loop;return true;end $$;
create or replace function ml_private.p3d_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(s->>'version'='web-v0.1.15',false)$$;
create or replace function ml_private.p3d_valid(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select not ml_private.p3d_enabled(s) or coalesce(jsonb_typeof(s#>'{stage3,d,clanUsed}')='array' and jsonb_array_length(s#>'{stage3,d,clanUsed}')=4 and not exists(select 1 from jsonb_array_elements(s#>'{stage3,d,clanUsed}') v where jsonb_typeof(v)<>'boolean'),false)$$;
create or replace function ml_private.p3d_start(s jsonb,a integer) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$begin
 if not ml_private.p3d_enabled(s) then return s;end if;s:=jsonb_set(s,'{stage3,d}',coalesce(s#>'{stage3,d}','{"clanUsed":[false,false,false,false]}'));return jsonb_set(s,array['stage3','d','clanUsed',a::text],'false');end $$;
create or replace function ml_private.p3d_clan_targets(s jsonb,a integer,active boolean) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(s->'order') with ordinality q(v,ord) where ml_private.stage4_on_board(s,(v#>>'{}')::int) and not(s#>>array['players',v#>>'{}','character']='character-027' and jsonb_array_length(s#>array['players',v#>>'{}','hand'])=1) and (active and (v#>>'{}')::int=a or s->>'mode'='team' and (v#>>'{}')::int<>a and s#>array['players',v#>>'{}','team']=s#>array['players',a::text,'team']) and ml_private.character_effect_allowed(jsonb_build_object('origin',case when active then 'role-active' else 'role-locked' end,'actor',a,'roleModifiers','[]'::jsonb),(v#>>'{}')::int,s#>>array['players',v#>>'{}','character'])
$$;
create or replace function ml_private.p3d_paid(s jsonb,a integer,before_ap integer,amount integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare t integer;begin
 if not ml_private.p3d_enabled(s) or s#>>array['players',a::text,'character']<>'character-053' or amount<=0 or before_ap<=0 or s#>>array['players',a::text,'ap']<>'0' or not ml_private.stage4_on_board(s,a) then return s;end if;
 for t in select (v#>>'{}')::int from ml_private.arr(ml_private.p3d_clan_targets(s,a,false)) v loop s:=ml_private.stage3_gain_ap(s,t,2);s:=s-'_gain';end loop;return ml_private.emit(s,'skill','S'||(a+1)||' 乞讨：其他存活队友各获得2AP');end $$;
create or replace function ml_private.p3d_pay(s jsonb,a integer,amount integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare previous integer:=(s#>>array['players',a::text,'ap'])::int;begin s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb(previous-amount));return ml_private.p3d_paid(s,a,previous,amount);end $$;
create or replace function ml_private.p3d_effect(s jsonb,a integer,card text,effect jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3d_enabled(s) and s#>>array['players',a::text,'character']='character-029' and split_part(card,'#',1)='basic-009' then jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','target'))) else effect end$$;
create or replace function ml_private.p3d_ball_allowed(s jsonb,a integer,t integer,converted boolean default false) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select not ml_private.p3d_enabled(s) or s#>>array['players',t::text,'character']<>'character-029' and ml_private.character_effect_allowed(jsonb_build_object('origin',case when converted then 'role-active' else 'card' end,'actor',a,'roleModifiers',case when s#>>array['players',a::text,'character']='character-029' then jsonb_build_array(jsonb_build_object('actor',a,'kind','target')) else '[]'::jsonb end),t,s#>>array['players',t::text,'character'])$$;
create or replace function ml_private.p3d_dodge_targets(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(ml_private.targets(s,a,'basic-009')) with ordinality q(v,ord) where ml_private.p3d_ball_allowed(s,a,(v#>>'{}')::int,true)$$;
create or replace function ml_private.p3d_injury(s jsonb,hits jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare a integer;h jsonb;jobs jsonb:='[]';begin
 if not ml_private.p3d_enabled(s) then return jobs;end if;
 for a in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop if not ml_private.stage4_on_board(s,a) then continue;end if;for h in select * from ml_private.arr(hits) loop if (h->>'loss')::int<=0 then continue;end if;
 if s#>>array['players',a::text,'character']='character-020' and s->>'mode'='team' and a<>(h->>'target')::int and s#>array['players',a::text,'team']=s#>array['players',h->>'target','team'] then jobs:=jobs||jsonb_build_array(ml_private.stage3_task('encourage',jsonb_build_object('actor',a,'data',jsonb_build_object('source',h->'source'))));end if;
 if s#>>array['players',a::text,'character']='character-029' and a=(h->>'target')::int then jobs:=jobs||jsonb_build_array(ml_private.stage3_task('nailong-shake',jsonb_build_object('actor',a)));end if;
 end loop;end loop;return jobs;end $$;
create or replace function ml_private.p3d_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=(t->>'actor')::int;src integer:=(t#>>'{data,source}')::int;roll integer;cell text;begin
 if t->>'action'='encourage' then if ml_private.stage4_on_board(s,a) then s:=ml_private.select_choice(s,'encourage',a,at,jsonb_build_object('data',t->'data'));end if;
 elsif t->>'action'='encourage-discard' then if ml_private.stage4_on_board(s,src) and jsonb_array_length(s#>array['players',src::text,'hand'])>0 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),src,s#>>array['players',src::text,'character']) then s:=ml_private.select_choice(s,'encourage-discard',src,at,jsonb_build_object('source',a,'count',least(2,jsonb_array_length(s#>array['players',src::text,'hand'])),'cards',s#>array['players',src::text,'hand']));end if;
 elsif t->>'action'='nailong-shake' and ml_private.stage4_on_board(s,a) then s:=ml_private.die(s,'摇');roll:=(s->>'_roll')::int;s:=s-'_roll';if roll<=4 then cell:=ml_private.stage3_direction_cell(s#>>array['players',a::text,'cell'],(array['left','right','up','down'])[roll]);if cell is not null and ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,cell,jsonb_build_array(a)) then s:=ml_private.stage3_relocate(s,a,cell,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;end if;
 end if;return s;end $$;
create or replace function ml_private.p3d_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;src integer;cards jsonb;begin
 if c->>'kind'='encourage' then if not timeout and cmd->>'accept'='true' and ml_private.stage4_on_board(s,a) then s:=ml_private.die(s,'鼓励队友');src:=(s->>'_roll')::int;s:=s-'_roll';if src%2=1 then s:=ml_private.draw(s,a,2);else src:=(c#>>'{data,source}')::int;if src is not null then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('encourage-discard',jsonb_build_object('actor',a,'data',jsonb_build_object('source',src)))));end if;end if;end if;return s;end if;
 if timeout then select coalesce(jsonb_agg(v),'[]') into cards from (select v from ml_private.arr(s#>array['players',a::text,'hand']) v order by v limit (c->>'count')::int) q;else cards:=coalesce(cmd->'cards','[]');end if;
 perform ml_private.need(jsonb_array_length(cards)=(c->>'count')::int and (select count(distinct v) from ml_private.arr(cards) v)=jsonb_array_length(cards) and c->'cards' @> cards and s#>array['players',a::text,'hand'] @> cards,'鼓励队友弃牌不合法');
 s:=jsonb_set(s,array['players',a::text,'hand'],(select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(s#>array['players',a::text,'hand']) with ordinality q(v,ord) where not(cards @> jsonb_build_array(v))));s:=ml_private.exercise_discard(s,cards);return ml_private.emit(s,'discard','S'||(a+1)||' 鼓励队友弃置'||jsonb_array_length(cards)||'张');end $$;
create or replace function ml_private.p3d_clan(s jsonb,a integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare cards jsonb:=s#>array['players',a::text,'hand'];t integer;begin
 perform ml_private.need(ml_private.p3d_enabled(s) and s#>>array['players',a::text,'character']='character-053' and ml_private.stage4_on_board(s,a) and s#>>array['stage3','d','clanUsed',a::text]='false' and jsonb_array_length(cards)>0,'鸡犬升天当前不可发动');
 s:=jsonb_set(s,array['stage3','d','clanUsed',a::text],'true');s:=jsonb_set(s,array['players',a::text,'hand'],'[]');s:=ml_private.exercise_discard(s,cards);
 for t in select (v#>>'{}')::int from ml_private.arr(ml_private.p3d_clan_targets(s,a,true)) v loop s:=ml_private.stage3_gain_ap(s,t,2);s:=s-'_gain';end loop;return ml_private.emit(s,'skill','S'||(a+1)||' 鸡犬升天：弃置全部'||jsonb_array_length(cards)||'张手牌，存活队友含自己各获得2AP');end $$;
